BEGIN;

ALTER TABLE warehouse_items
  ADD COLUMN IF NOT EXISTS subcategoria VARCHAR(50);

CREATE INDEX IF NOT EXISTS idx_warehouse_items_subcategoria
  ON warehouse_items(subcategoria);

ON CONFLICT (codigo) DO UPDATE SET
  nome = EXCLUDED.nome,
